def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    fixed_david_like = False
    high_pressure = 0.0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > high_pressure:
                    high_pressure = float(bid)
                if abs(float(bid) - 15.0) < 1e-9:
                    fixed_david_like = True

    if budget <= 0:
        return 0.0

    competitors = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < competitors

    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    if not alive:
        bid = DAILY_SALARY * 0.35
        return float(min(budget, max(0.0, bid)))

    target = 0.0

    if urgent:
        if scarcity:
            target = 58.0
        else:
            target = 36.0
        if high_pressure >= 50.0:
            target = max(target, 60.0)
    elif semi_urgent:
        if fixed_david_like:
            target = 16.2 if scarcity else 15.6
        else:
            if high_pressure >= 50.0:
                target = 18.0 if not scarcity else 24.0
            else:
                target = max(15.5, high_pressure + 1.1) if high_pressure > 0 else 15.5
    else:
        if scarcity:
            if fixed_david_like:
                target = 16.1
            elif high_pressure >= 50.0:
                target = 8.0
            elif high_pressure >= 20.0:
                target = 14.0
            else:
                target = 15.2
        else:
            if high_pressure >= 50.0:
                target = 5.0
            elif fixed_david_like:
                target = 15.4
            elif high_pressure > 0:
                target = min(16.0, high_pressure + 0.6)
            else:
                target = 14.0

    if day >= 8 and hp <= 6:
        target = max(target, 24.0)
    if day >= 9 and no_water >= 1:
        target = max(target, 40.0)

    if budget < target:
        target = budget

    if not urgent and high_pressure >= 55.0 and not scarcity:
        target = min(target, 10.0)

    return float(max(0.0, min(budget, target)))
